import{_ as a,o as t,c as r,a6 as p}from"./chunks/framework.QQy01QNh.js";const h=JSON.parse('{"title":"D.16　组织、工作、领导与劳动保护","description":"","frontmatter":{"title":"D.16　组织、工作、领导与劳动保护"},"headers":[],"relativePath":"theory/appendix-d/d-16.md","filePath":"theory/appendix-d/d-16.md"}'),o={name:"theory/appendix-d/d-16.md"};function i(d,e,n,s,c,_){return t(),r("div",null,[...e[0]||(e[0]=[p('<div class="theory-source"><h1 id="section-d-16" tabindex="-1">D.16　组织、工作、领导与劳动保护 <a class="header-anchor" href="#section-d-16" aria-label="Permalink to &quot;D.16　组织、工作、领导与劳动保护 {#section-d-16}&quot;">​</a></h1><p>正文连接：§6.3—6.5；§7.6；§8；§15.3.3。研究入口：16.01—16.09。</p><p>组织的成立、增长、分化、探索与利用、资源依赖、制度化和退出，需要连接任务、知识、资源、权限与实际工作链。组织生命周期模型可以提出阶段性条件问题，却不能把所有组织放进必经顺序；法人、工作网络、知识与服务也未必同时开始或结束。</p><p>组织学习须区分形成方案、留下记录、实际调用、持久改变与结果。对某一反馈介导学习分支的专门检验未完成，不取消已经能够追踪的一般学习过程；一次培训或写入制度，也不能自动证明后续任务改善。同构规则可以提供协调与保护，脱耦可能出现在文本、执行或结果的不同层面，不全等于欺骗。</p><p>专业与非正式网络可能弥补正式流程，也可能让无关系者被排除。领导的组织作用应落实到议程、资源、解释、授权和纠错，而不以个人特质承担全部成功失败。劳动评价要分工时、节奏、技能、收入、健康、隐性维护和照护，不把产量当作全部工作质量。</p><p>比较工时资料时，法定上限、加班报酬阈值、排班和实际工作时数应按适用人群、计时单位、实施阶段与例外分别核对。</p><p>劳动者共同决定应落实到具体事项，区别提出议题、取得信息、咨询、谈判、共同同意、争议裁决与组织内部自主制定。劳动者可以形成自己的互助和工作规则；改变雇主或平台规则的权限则须另核。会员、所有者、受雇者与被代表者未必重合，提名、问责和内部异议也不能由一次投票代替。</p><p>教学例：换一个负责人后产出恢复，但仍由少数人持续加班补缺。产出改善是真实结果；可持续性、分配与接续仍待判断。退出、分裂、合并和集体谈判须检查合同、知识、代表范围、实际执行与反报复；框架分析资格不能被挪作劳动者组织和申诉的入场门。</p><p>组织记忆的故障可以发生在保存、检索、知悉、处理和后果的不同位置。旧信息已被调用而未进入处置时，继续笼统归为失忆会遗漏组织阻断。负责人离开所造成的冲击可以识别一种具体依赖，却不能独自回答从未有过此人的世界。组织存续、工作能力、程序改善和劳动者生活分别作为结果，已成立的一项不替其他项作证。</p><p>专题定位：16.01 组织生命周期：Greiner、Adizes；16.02 探索与利用、组织学习：March、Argyris、Schön；16.03 资源依赖与制度化：Pfeffer、Salancik、Selznick；16.04 制度同构、脱耦与组织合法性：Meyer、Rowan、DiMaggio、Powell；16.05 科层、专业组织与非正式网络；16.06 领导、创业与集体生成；16.07 劳动过程、指标、激励与倦怠；16.08 退出、分裂、合并与组织记忆；16.09 劳动者组织、集体谈判与劳动保护。</p></div>',1)])])}const f=a(o,[["render",i]]);export{h as __pageData,f as default};
